     3	/**
     4	 * A real international phone input: a searchable country dropdown (flag +
     5	 * dial code) plus a national-number field, backed by libphonenumber-js for
     6	 * real per-country validation and live formatting — replacing the old plain
     7	 * `+1.5551234567` free-text field (validated only against a shape regex,
     8	 * never against whether the number could exist).
     9	 *
    10	 * The WIRE VALUE this emits is unchanged: `+<dialcode>.<nationalnumber>`,
    11	 * exactly the format `purchaseDomain`'s zod schema
    12	 * (`/^\+\d{1,3}\.\d{4,14}$/`) expects. This component is a client-side
    13	 * affordance on top of that format, not a new format — the server-side
    14	 * contract in lib/actions-domains.ts is untouched.
    15	 *
    16	 * No new icon/flag assets: country flags are Unicode regional-indicator
    17	 * emoji, derived from the ISO-3166 alpha-2 code (two code points, no image,
    18	 * no icon font, no CDN).
    19	 */
    20	
    21	import { useEffect, useMemo, useRef, useState } from "react";
    22	import {
    23	  AsYouType,
    24	  getCountries,
    25	  getCountryCallingCode,
    26	  parsePhoneNumberFromString,
    27	  type CountryCode,
    28	} from "libphonenumber-js";
    29	
    30	function flagEmoji(iso2: string): string {
    31	  return String.fromCodePoint(...[...iso2.toUpperCase()].map((c) => 127397 + c.charCodeAt(0)));
    32	}
    33	
    34	// `Intl.DisplayNames` gives us real, localized country names with no hardcoded
    35	// list to maintain — supported in Node 14+ and every modern browser, so this
    36	// never needs an extra dependency or a data file.
    37	const regionNames =
    38	  typeof Intl !== "undefined" && "DisplayNames" in Intl
    39	    ? new Intl.DisplayNames(["en"], { type: "region" })
    40	    : null;
    41	
    42	function countryName(iso2: string): string {
    43	  return regionNames?.of(iso2) ?? iso2;
    44	}
    45	
    46	type CountryEntry = { code: CountryCode; name: string; dial: string; flag: string };
    47	
    48	/** Built once at module load — libphonenumber-js's supported-country list never
    49	 *  changes at runtime, so there is no reason to recompute this per render. */
    50	const ALL_COUNTRIES: CountryEntry[] = getCountries()
    51	  .map((code) => {
    52	    let dial = "";
    53	    try {
    54	      dial = getCountryCallingCode(code);
    55	    } catch {
    56	      dial = "";
    57	    }
    58	    return { code, name: countryName(code), dial, flag: flagEmoji(code) };
    59	  })
    60	  .filter((c) => c.dial)
    61	  .sort((a, b) => a.name.localeCompare(b.name));
    62	
    63	/** Wire value ("+1.5551234567") -> best-guess ISO2 country, or null. Used only
    64	 *  to seed the widget from an existing value (e.g. re-rendering with a value
    65	 *  already typed); libphonenumber-js resolves the region from the full E.164
    66	 *  string itself, so a shared dial code (NANP's +1, etc.) still lands on a
    67	 *  sensible default. */
    68	function countryFromWire(wire: string): CountryCode | null {
    69	  const e164 = wire.replace(".", "");
    70	  if (!e164.startsWith("+")) return null;
    71	  return parsePhoneNumberFromString(e164)?.country ?? null;
    72	}
    73	
    74	function nationalFromWire(wire: string): string {
    75	  const dot = wire.indexOf(".");
    76	  return dot >= 0 ? wire.slice(dot + 1) : "";
    77	}
