158	   157	  const router = useRouter();
159	   158	  const fired = useRef(false);
160	   159	  const [state, setState] = useState<FinalizeState>({ kind: "working" });
161	   160	  const canceled = sessionId === "canceled";
162	   161	
163	   162	  useEffect(() => {
164	   163	    if (canceled || fired.current) return;
165	   164	    fired.current = true;
166	   165	    void (async () => {
167	   166	      const res = await finalizeCardSetup(sessionId);
168	   167	      if (res.ok) {
169	   168	        setState({ kind: "saved", label: res.label ?? "Card saved" });
170	   169	        // Fire-and-forget "card" conversion (→ Meta AddPaymentInfo + the Google Ads
171	   170	        // card label). Best-effort: a no-op until consent + the pixel load.
172	   171	        try {
173	   172	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("card", {});
174	   173	        } catch {
175	   174	          /* ignore */
176	   175	        }
