178	   177	        // doesn't replay the return leg, then pull the page's server data again —
179	   178	        // the action has already revalidated it.
180	   179	        router.replace("/dashboard/billing");
181	   180	        router.refresh();
182	   181	        return;
183	   182	      }
184	   183	      setState({ kind: "failed", error: res.error ?? "The card wasn't saved." });
185	   184	    })();
186	   185	  }, [sessionId, canceled, router]);
187	   186	
188	   187	  if (canceled) {
189	   188	    return (
190	   189	      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
191	   190	        <p className="text-sm font-medium text-amber-300">Card setup canceled</p>
