260	   260	/**
261	   261	 * Redeem a gift code into the current user's wallet. Race-safe: the claim is an
262	   262	 * `updateMany` guarded by `redeemedById: null` inside a transaction, so two
263	   263	 * concurrent redemptions of the same code can only ever succeed once.
264	   264	 */
265	   265	export async function redeemGiftCode(
266	   266	  rawCode: string
267	   267	): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
268	   268	  const user = await requireUser();
269	   269	  const code = String(rawCode ?? "").trim().toUpperCase();
270	   270	  if (!code) return { error: "Enter a gift code." };
271	   271	
272	   272	  const gift = await db.giftCode.findUnique({ where: { code } });
273	   273	  // Not a single-use gift code? It might be a multi-use CREDIT_CENTS coupon
274	   274	  // (e.g. a "free month" promo) — redeem that for wallet credit, no purchase.
275	   275	  if (!gift) return redeemCreditCoupon(user, code);
276	   276	  if (gift.redeemedById) return { error: "This code has already been redeemed." };
277	   277	
278	   278	  const result = await db.$transaction(async (tx) => {
279	   279	    // Atomic claim: only succeeds if the code is still unredeemed.
280	   280	    const claim = await tx.giftCode.updateMany({
281	   281	      where: { id: gift.id, redeemedById: null },
282	   282	      data: { redeemedById: user.id, redeemedAt: new Date() },
283	   283	    });
284	   284	    if (claim.count !== 1) return { error: "This code has already been redeemed." };
285	   285	
286	   286	    await tx.user.update({
287	   287	      where: { id: user.id },
288	   288	      data: { balanceCents: { increment: gift.amountCents } },
289	   289	    });
290	   290	    await tx.walletTransaction.create({
291	   291	      data: {
292	   292	        userId: user.id,
293	   293	        amountCents: gift.amountCents,
294	   294	        description: `Gift code redeemed (${gift.code})`,
295	   295	      },
296	   296	    });
297	   297	    return { ok: true, amountCents: gift.amountCents };
298	   298	  });
299	   299	
300	   300	  if (result.ok) {
301	   301	    revalidatePath("/dashboard/billing");
302	   302	  }
303	   303	  return result;
304	   304	}
