306	   306	/**
307	   307	 * Redeem a multi-use CREDIT_CENTS coupon (e.g. a "free month" promo) straight
308	   308	 * into the wallet — no top-up/purchase required. Enforces enabled / active /
309	   309	 * expiry / per-coupon `maxRedemptions` / one-per-user / first-time-only, all
310	   310	 * race-safe: the limit is an atomic conditional increment, and the per-user cap
311	   311	 * is the `@@unique([couponId,userId])` on CouponRedemption (a concurrent
312	   312	 * double-redeem throws and rolls the whole transaction back).
313	   313	 */
314	   314	async function redeemCreditCoupon(
315	   315	  user: User,
316	   316	  code: string
317	   317	): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
318	   318	  if (!(await getSettingBool("coupons_enabled", true))) {
319	   319	    return { error: "Promo codes are currently disabled." };
320	   320	  }
321	   321	  const coupon = await db.coupon.findUnique({ where: { code } });
322	   322	  if (!coupon || !coupon.active) {
323	   323	    return { error: "That code isn't valid. Check for typos and try again." };
324	   324	  }
325	   325	  if (coupon.kind !== "CREDIT_CENTS") {
326	   326	    // PERCENT / FIXED_CENTS are discounts on a top-up, entered when adding funds.
327	   327	    return { error: "This code is a discount on a top-up — enter it when you add funds." };
328	   328	  }
329	   329	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
330	   330	    return { error: "This code has expired." };
331	   331	  }
332	   332	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
333	   333	    return { error: "This code has reached its redemption limit." };
334	   334	  }
335	   335	  const already = await db.couponRedemption.findUnique({
336	   336	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
337	   337	  });
338	   338	  if (already) return { error: "You've already used this code." };
339	   339	  if (coupon.firstTimeOnly) {
340	   340	    const priorCredits = await db.walletTransaction.count({
341	   341	      where: { userId: user.id, amountCents: { gt: 0 } },
342	   342	    });
343	   343	    if (priorCredits > 0) return { error: "This code is for first-time customers only." };
344	   344	  }
345	   345	
346	   346	  const result = await db
347	   347	    .$transaction(async (tx) => {
348	   348	      // Atomic limit claim — only proceeds while under the cap (skipped if uncapped).
349	   349	      if (coupon.maxRedemptions !== null) {
350	   350	        const claim = await tx.coupon.updateMany({
351	   351	          where: { id: coupon.id, timesRedeemed: { lt: coupon.maxRedemptions } },
352	   352	          data: { timesRedeemed: { increment: 1 } },
353	   353	        });
354	   354	        if (claim.count !== 1) return { error: "This code has reached its redemption limit." };
355	   355	      } else {
356	   356	        await tx.coupon.update({ where: { id: coupon.id }, data: { timesRedeemed: { increment: 1 } } });
357	   357	      }
358	   358	      // One-per-user via the unique constraint (a race throws → full rollback).
359	   359	      await tx.couponRedemption.create({
360	   360	        data: { couponId: coupon.id, userId: user.id, amountCents: coupon.value, context: "free-credit" },
361	   361	      });
362	   362	      await tx.user.update({
363	   363	        where: { id: user.id },
364	   364	        data: { balanceCents: { increment: coupon.value } },
365	   365	      });
366	   366	      await tx.walletTransaction.create({
367	   367	        data: { userId: user.id, amountCents: coupon.value, description: `Promo code redeemed (${coupon.code})` },
368	   368	      });
369	   369	      return { ok: true, amountCents: coupon.value };
370	   370	    })
371	   371	    .catch(() => ({ error: "You've already used this code." }) as { error: string });
372	   372	
373	   373	  if ("ok" in result && result.ok) revalidatePath("/dashboard/billing");
374	   374	  return result;
375	   375	}
376	   376	// Customer-facing view of the dunning ladder.
377	   377	//
378	   378	// WHY THIS FILE EXISTS
379	   379	// `worker/billing.ts` owns the dunning POLICY, and every constant that shapes it
380	   380	// (`retryDayFor`, `CARD_SUSPEND_DAY`, `DUNNING_EXHAUSTED`, `SUSPEND_SLIP_CAP_DAYS`,
381	   381	// `suspendDueAt`) is module-private there. The portal cannot import them: that file
382	   382	// pulls in the provisioning worker's whole world — Proxmox, nodemailer, the job
383	   383	// queue — and none of it belongs in a page bundle.
384	   384	//
385	   385	// So the DAY ARITHMETIC is duplicated here, deliberately, and each constant is
386	   386	// named exactly as the worker names it so a change to the schedule is greppable.
387	   387	// This is the same trade `lib/actions-settings.ts` already makes for
388	   388	// MIN_TERMINATE_DAYS, and it is guarded the same way: `test/payment-method-ui.test.ts`
389	   389	// reads worker/billing.ts and fails the moment the two disagree.
390	   390	//
391	   391	// DUNNING_RETRY_ATTEMPTS itself is IMPORTED rather than copied. It is the one number
392	   392	// the dunning emails subtract from ("we'll try 2 more times"), and a second copy of
393	   393	// it is precisely how that promise starts outliving the retries that back it.
394	   394	//
395	   395	// Plain server module. Everything below is pure arithmetic on the columns the worker
396	   396	// writes, so a server component can compute the view once and hand plain data to a
397	   397	// client component — no clock or database access hides in here.
398	   398	
399	   399	import { DUNNING_RETRY_ATTEMPTS } from "./mailer";
400	   400	
401	   401	export { DUNNING_RETRY_ATTEMPTS };
402	   402	
403	   403	const DAY = 86_400_000;
404	   404	
405	   405	/** Mirrors `const retryDayFor = (retry: number) => 2 * retry - 1;` in worker/billing.ts. */
406	   406	export const retryDayFor = (retry: number) => 2 * retry - 1;
407	   407	/** Mirrors `const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;` — one clear day after the final notice. */
408	   408	const SUSPEND_DAYS_AFTER_LAST_RETRY = 1;
409	   409	/** Mirrors `const SUSPEND_SLIP_CAP_DAYS = 4;` in worker/billing.ts. */
410	   410	export const SUSPEND_SLIP_CAP_DAYS = 4;
411	   411	/**
412	   412	 * Mirrors `const CARD_EXPIRY_WARN_DAYS = 30;` in worker/billing.ts — how far ahead
413	   413	 * the worker emails about a card that is about to expire. The portal flags the card
414	   414	 * on exactly the same day the email goes out, so the two never disagree about
415	   415	 * whether a card counts as "expiring soon".
416	   416	 */
417	   417	export const CARD_EXPIRY_WARN_DAYS = 30;
418	   418	
419	   419	/** Days past expiry on which the worker retries the saved card. */
420	   420	export const RETRY_DAYS: number[] = Array.from({ length: DUNNING_RETRY_ATTEMPTS }, (_, i) =>
421	   421	  retryDayFor(i + 1),
422	   422	);
423	   423	/** Days past expiry of the LAST automatic retry. */
424	   424	export const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
425	   425	/** Days past expiry when a card customer's server pauses, if nothing has been paid. */
426	   426	export const CARD_SUSPEND_DAY = LAST_RETRY_DAY + SUSPEND_DAYS_AFTER_LAST_RETRY;
427	   427	/**
428	   428	 * `Server.dunningStage` once every automatic attempt is spent: the attempt made on
429	   429	 * expiry day itself, plus one per retry. Mirrors
430	   430	 * `const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;`.
431	   431	 */
432	   432	export const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;
433	   433	
434	   434	/** The columns `worker/billing.ts` reads to decide what happens to an overdue server. */
435	   435	export type DunningInput = {
436	   436	  expiresAt: Date | null;
437	   437	  dunningStage: number;
438	   438	  dunningNextAt: Date | null;
439	   439	};
440	   440	
441	   441	export type DunningView = {
442	   442	  /** Whether this account can actually be auto-charged — changes the whole ladder. */
443	   443	  hasCard: boolean;
444	   444	  /** True once at least one automatic card attempt has FAILED for this period. */
445	   445	  inDunning: boolean;
446	   446	  /** Automatic attempts already spent (the expiry-day attempt plus any retries). */
447	   447	  attemptsMade: number;
448	   448	  /**
449	   449	   * Every automatic attempt the ladder will ever make. Zero without a card: the
450	   450	   * worker makes no attempt at all, so promising four would be a lie.
451	   451	   */
452	   452	  attemptsTotal: number;
453	   453	  /** Attempts still to come. Zero means the final notice has already been sent. */
454	   454	  attemptsLeft: number;
455	   455	  /** True once every automatic attempt is spent — suspension is the next event. */
456	   456	  exhausted: boolean;
457	   457	  /** When the worker will next try the card. Null when nothing is scheduled. */
458	   458	  nextAttemptAt: Date | null;
459	   459	  /**
460	   460	   * When the server pauses if nothing is paid — the same expression `suspendDueAt`
461	   461	   * evaluates, including the promise-keeping slip and its cap. Null when the admin
462	   462	   * kill switch has auto-suspend off, in which case nothing pauses on a timer.
463	   463	   */
464	   464	  suspendAt: Date | null;
465	   465	  /** Whole days since the term ran out. Negative before expiry. */
466	   466	  daysPastExpiry: number;
467	   467	};
468	   468	
469	   469	/**
470	   470	 * Days past expiry of the plain calendar deadline, before any late-sequence slip.
471	   471	 * Mirrors `calendarSuspendDay` in worker/billing.ts.
472	   472	 */
473	   473	function calendarSuspendDay(graceDays: number, hasCard: boolean): number {
474	   474	  return hasCard ? Math.max(graceDays, CARD_SUSPEND_DAY) : graceDays;
475	   475	}
476	   476	
477	   477	/**
478	   478	 * Mirrors `suspendDueAt` in worker/billing.ts, including the rule that a suspension
479	   479	 * never lands before a retry date we have already promised the customer by email —
480	   480	 * and that the slip that buys is capped, so a Stripe outage cannot defer it forever.
481	   481	 */
482	   482	function suspendDueAt(
483	   483	  server: DunningInput,
484	   484	  hasCard: boolean,
485	   485	  cfg: { graceDays: number; autoSuspend: boolean },
486	   486	): Date | null {
487	   487	  if (!cfg.autoSuspend || !server.expiresAt) return null;
488	   488	  const days = calendarSuspendDay(cfg.graceDays, hasCard);
489	   489	  const at = new Date(server.expiresAt.getTime() + days * DAY);
490	   490	  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
491	   491	  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
492	   492	  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
493	   493	}
494	   494	
495	   495	/**
496	   496	 * Turn the raw dunning columns into something a customer can be told without
497	   497	 * over-promising.
498	   498	 *
499	   499	 * Two states the UI must never conflate, which is why they are separate fields:
500	   500	 * a customer with NO card is not "0 of 4 attempts made" — the worker will never
501	   501	 * attempt anything for them, and they go to grace and then suspension on the
502	   502	 * shorter clock. `attemptsTotal` is 0 in that case rather than 4.
503	   503	 */
504	   504	export function dunningView(
505	   505	  server: DunningInput,
506	   506	  opts: { hasCard: boolean; graceDays: number; autoSuspend: boolean; now: Date },
507	   507	): DunningView {
508	   508	  const { hasCard, graceDays, autoSuspend, now } = opts;
509	   509	  const attemptsMade = hasCard ? Math.min(Math.max(0, server.dunningStage), DUNNING_EXHAUSTED) : 0;
510	   510	  const attemptsTotal = hasCard ? DUNNING_EXHAUSTED : 0;
511	   511	  return {
512	   512	    hasCard,
513	   513	    inDunning: server.dunningStage > 0,
514	   514	    attemptsMade,
515	   515	    attemptsTotal,
516	   516	    attemptsLeft: Math.max(0, attemptsTotal - attemptsMade),
517	   517	    exhausted: hasCard && server.dunningStage >= DUNNING_EXHAUSTED,
518	   518	    nextAttemptAt: hasCard ? server.dunningNextAt : null,
519	   519	    suspendAt: suspendDueAt(server, hasCard, { graceDays, autoSuspend }),
520	   520	    daysPastExpiry: server.expiresAt
521	   521	      ? Math.floor((now.getTime() - server.expiresAt.getTime()) / DAY)
522	   522	      : 0,
523	   523	  };
524	   524	}
525	   525	// Spend caps + monthly-budget alerts (Finding 3). Plain server module.
526	   526	//
527	   527	// "Spend" here means MONEY ACTUALLY CHARGED FOR SERVICES this calendar month: the
528	   528	// sum of the negative `WalletTransaction` amounts (orders, renewals, resizes). Wallet
529	   529	// TOP-UPS are positive credits and are never counted — adding money to the wallet is
530	   530	// not spending it, and a hard cap must never block a customer topping up to pay a
531	   531	// bill. Refund credits are likewise positive and excluded.
532	   532	//
533	   533	// Two features, both opt-in and both defaulting OFF so an account that has not
534	   534	// configured them behaves exactly as before:
535	   535	//   • a SOFT monthly budget that emails once when spend first crosses it, and
536	   536	//   • a HARD monthly cap that REFUSES a new paid order / manual wallet renewal that
537	   537	//     would push spend past it.
538	   538	//
539	   539	// The hard cap is enforced at the discretionary spend paths (placeOrder, renewNow),
540	   540	// NOT in the automatic auto-renew sweep: a standing auto-renew instruction must not
541	   541	// silently lapse and destroy an existing server because of a budget number.
542	   542	
543	   543	import { db } from "./db";
544	   544	import type { Prisma } from "@prisma/client";
545	   545	
546	   546	export class SpendCapError extends Error {
547	   547	  constructor(message: string) {
548	   548	    super(message);
549	   549	    this.name = "SpendCapError";
550	   550	  }
551	   551	}
552	   552	
553	   553	/** "YYYY-MM" for a date in UTC — the bucket both spend-to-date and the alert use. */
554	   554	export function monthKey(d: Date = new Date()): string {
555	   555	  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
556	   556	}
557	   557	
558	   558	/** First instant of the current UTC calendar month. */
559	   559	export function startOfMonth(d: Date = new Date()): Date {
560	   560	  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1));
561	   561	}
562	   562	
563	   563	/**
564	   564	 * Service spend (in cents, positive) for this account so far this calendar month:
565	   565	 * the magnitude of every negative wallet transaction since the month began. Runs on
566	   566	 * the passed transaction client when given one so a caller can read it inside the
567	   567	 * same tx that is about to debit.
568	   568	 */
569	   569	export async function monthSpendCents(
570	   570	  userId: string,
571	   571	  client: Prisma.TransactionClient | typeof db = db,
572	   572	  now: Date = new Date(),
573	   573	): Promise<number> {
574	   574	  const agg = await client.walletTransaction.aggregate({
575	   575	    where: { userId, amountCents: { lt: 0 }, createdAt: { gte: startOfMonth(now) } },
576	   576	    _sum: { amountCents: true },
577	   577	  });
578	   578	  return Math.abs(agg._sum.amountCents ?? 0);
579	   579	}
580	   580	
581	   581	/**
582	   582	 * Refuse a new discretionary charge of `addCents` when the account has a hard cap
583	   583	 * enabled and this charge would push month-to-date spend past it. No-op when the cap
584	   584	 * is disabled or unset. Throws SpendCapError (a clear, customer-facing message) so
585	   585	 * the order/renew action can surface it verbatim.
586	   586	 *
587	   587	 * Advisory-but-safe: the cap is the customer's OWN limit, not a security boundary, so
588	   588	 * a read-then-charge check is acceptable; it is called immediately before the debit.
589	   589	 */
590	   590	export async function assertSpendCap(
591	   591	  user: { id: string; spendCapEnabled?: boolean; hardCapCents?: number | null },
592	   592	  addCents: number,
593	   593	  client: Prisma.TransactionClient | typeof db = db,
594	   594	): Promise<void> {
595	   595	  if (!user.spendCapEnabled || user.hardCapCents == null || addCents <= 0) return;
596	   596	  const cap = user.hardCapCents;
597	   597	  const spent = await monthSpendCents(user.id, client);
598	   598	  if (spent + addCents > cap) {
599	   599	    const remain = Math.max(0, cap - spent);
600	   600	    throw new SpendCapError(
601	   601	      `This purchase ($${(addCents / 100).toFixed(2)}) would exceed your monthly spend cap of ` +
602	   602	        `$${(cap / 100).toFixed(2)} — you have $${(remain / 100).toFixed(2)} left this month. ` +
603	   603	        `Raise or turn off the cap in Billing to continue.`,
604	   604	    );
605	   605	  }
606	   606	}
607	   607	
608	   608	/**
609	   609	 * After a charge lands, email the customer at most ONCE per calendar month the first
610	   610	 * time their month-to-date spend crosses their soft budget. Best-effort and
611	   611	 * idempotent via `budgetAlertedPeriod`; never throws into the charge path.
612	   612	 */
613	   613	export async function maybeAlertBudget(userId: string): Promise<void> {
614	   614	  try {
615	   615	    const user = await db.user.findUnique({ where: { id: userId } });
616	   616	    if (!user || !user.budgetAlertEnabled || user.monthlyBudgetCents == null) return;
