// ---------- Wallet (demo top-up until a payment gateway is connected) ----------

export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  // Spend/credit path: block while impersonating so an admin can't mint or move
  // a customer's balance on their behalf.
  await assertNotImpersonating();
  // Security: never mint free wallet balance in production. The demo gateway that
  // credits without a real payment is only ever acceptable in non-production, and
  // is refused outright when NODE_ENV === "production" regardless of Stripe.
  if (process.env.NODE_ENV === "production") {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
  // go through Checkout.
  const { stripeConfigured } = await import("./stripe");
  if (stripeConfigured()) {
    return { error: "Please add funds with a card via the secure checkout." };
  }
  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
  const topupIp = clientIp(await headers());
  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
  if (!topupRl.ok) {
    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
  }
  const amount = Number(formData.get("amount"));
  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
    return { error: "Amount must be between $1 and $1000." };
  }
  const cents = Math.round(amount * 100);
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (cents < minTopup) {
    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
  }

  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
  // sets. applyCouponToTopup re-validates for this user against the real amount.
  const jar = await cookies();
  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
  let bonusCents = 0;
  let couponId: string | null = null;
  let couponLabel = "";
  if (couponCode) {
    const result = await applyCouponToTopup(couponCode, cents);
    if (result.ok) {
      bonusCents = result.bonusCents;
      couponId = result.couponId;
      couponLabel = result.label;
    } else {
      // REFUSE, don't silently drop. The old code fell through and completed the
      // top-up with no bonus and no message, so a code that passed validation at
      // the preview amount but fails against the real one (a `minAmountCents`
      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
      // charged at this point, so stopping is free and the customer can retry
      // without the code or with a larger amount.
      return {
        error:
          `${result.error ?? "That promo code can't be applied to this amount."} ` +
          `Nothing has been charged — adjust the amount or remove the code and try again.`,
      };
    }
  }

  try {
    await db.$transaction(async (tx) => {
      // Claim the coupon FIRST, atomically. The old code did an unconditional
      // `coupon.update({ timesRedeemed: { increment: 1 } })` after a plain read of
      // the cap in the preview, so two top-ups racing for the last slot both saw
      // room and both incremented — the limit could be blown past by any number of
      // concurrent claims. Mirror `claimOrderCoupon`: a conditional `updateMany`
      // gated on `timesRedeemed < max` is the only thing that atomically hands out
      // the final slot, and the unique(coupon,user) create fails a double-claim.
      if (bonusCents > 0 && couponId) {
        const c = await tx.coupon.findUnique({ where: { id: couponId }, select: { maxRedemptions: true } });
        const claim = await tx.coupon.updateMany({
          where:
            c?.maxRedemptions == null
              ? { id: couponId, active: true }
              : { id: couponId, active: true, timesRedeemed: { lt: c.maxRedemptions } },
          data: { timesRedeemed: { increment: 1 } },
        });
        if (claim.count !== 1) throw new CouponClaimError("That code has just reached its redemption limit.");
        try {
          await tx.couponRedemption.create({
            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
          });
        } catch {
          throw new CouponClaimError("You’ve already used this code.");
        }
      }
      await tx.user.update({
        where: { id: user.id },
        data: { balanceCents: { increment: cents + bonusCents } },
      });
      await tx.walletTransaction.create({
        data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
      });
      if (bonusCents > 0 && couponId) {
        await tx.walletTransaction.create({
          data: {
            userId: user.id,
            amountCents: bonusCents,
            description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
          },
        });
      }
    });
  } catch (e) {
    // The demo gateway charges nothing external, so a rolled-back transaction
    // means the customer is untouched — safe to surface and let them retry.
    if (e instanceof CouponClaimError) {
      return { error: `${e.message} Nothing has been charged — remove the code and try again.` };
    }
    throw e;
  }
  jar.delete(COUPON_COOKIE);
  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
  // First successful paid action may unlock a referral reward for both parties.
  try {
    await maybeRewardReferral(user.id);
  } catch { /* non-fatal */ }
  revalidatePath("/dashboard/billing");
  return {};
}

// ---------- Subscriptions ----------

export async function toggleAutoRenew(serverId: string) {
  const { user, server } = await ownedServer(serverId);
  if (server.isFree) return;
  await db.server.update({
    where: { id: serverId },
    data: { autoRenew: !server.autoRenew },
  });
  await audit(user.id, "server.autorenew_toggle", `${serverId} -> ${!server.autoRenew}`);
  revalidatePath(`/dashboard/servers/${serverId}`);
}

export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  if (server.isFree || !server.expiresAt) return;
  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
  // cannot strand an existing customer: every account that owns a server today
  // predates verification and is grandfathered, and the automatic renewal in
  // worker/billing.ts does not pass through here at all — nobody's server lapses
  // because of this check.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const plan = await db.plan.findUnique({ where: { id: server.planId } });
  if (!plan) return;
  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
  const gamePlan = server.gamePlanId
    ? await db.gamePlan.findUnique({
        where: { id: server.gamePlanId },
        select: { name: true, priceCents: true, termMonths: true },
      })
    : null;
  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
    where: { serverId }, select: { id: true },
  }));
  // The SERVER OWNER (not necessarily the acting user) determines the VAT/GST rate
  // and the spend cap — resolved up front so `renewalQuote` prices tax-inclusive.
  const owner = await db.user.findUnique({ where: { id: server.userId } });
  if (!owner) return;
  const renewTaxCtx = await taxContextForUser(owner);
  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
  // in worker/billing.ts and the saved-card path use. Not a second copy of the
  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
  // rule, the second of which was a fresh duplicate written hours after the first.
  const quote = renewalQuote(
    {
      termMonths: server.termMonths,
      extraDiskGB: server.extraDiskGB,
      plan: { name: plan.name, priceCents: plan.priceCents },
      gamePlan,
      dedicatedIp: hasDedicatedIp ? {} : null,
      backupTier: server.backupTier,
    },
    {
      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
      extraDiskPerGbCents: await extraDiskPerGbCents(),
      backupPlusCents: await backupPlusMonthlyCents(),
      annualDiscountPct: await annualDiscountPct(),
      // VAT/GST for the owner's country (Finding 1). `renewCents` below is

 *                     transaction, with a ledger line and a credit-note invoice.
 *
 * Ownership-guarded and `assertNotImpersonating` (this both destroys a resource and
 * can move money — an admin must not do either on a customer's behalf). Respects the
 * one-in-flight-job invariant. The confirm dialog in the UI carries the data-retention
 * warning and the refund figure.
 */
export async function cancelService(
  serverId: string,
  mode: "immediate" | "period_end",
): Promise<{ error?: string; ok?: boolean; refundCents?: number; message?: string }> {
  // Moves money and destroys a resource — never while impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);

  if (server.status === "DELETING") return { error: "This server is already being cancelled." };

  // ---- Cancel at period end: just stop auto-renew, keep the server to expiry. ----
  if (mode === "period_end") {
    if (server.isFree || !server.expiresAt) {
      return { error: "This server has no billing term to cancel — use immediate termination to remove it." };
    }
    if (!server.autoRenew) {
      return { ok: true, message: `Auto-renew is already off. This server stays active until ${server.expiresAt.toISOString().slice(0, 10)}, then stops.` };
    }
    await db.server.update({ where: { id: server.id }, data: { autoRenew: false } });
    await db.auditLog.create({
      data: { userId: user.id, action: "server.cancel_period_end", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return {
      ok: true,
      message: `Auto-renew turned off. This server keeps running until ${server.expiresAt.toISOString().slice(0, 10)}, then stops automatically. You can turn auto-renew back on any time before then.`,
    };
  }

  // ---- Immediate termination (+ prorated wallet refund). ----
  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server. Wait for it to finish, then try again." };
  }

  const refundCents = terminationRefundCents({
    isFree: server.isFree,
    expiresAt: server.expiresAt,
    isGame: !!server.gamePlanId,
    planMonthlyCents: server.plan.priceCents,
    termMonths: server.termMonths,
    termPromoPercent: server.termPromoPercent,
    // Authoritative refund basis: the real plan cash collected for the term, net of
    // promo AND coupon. Null on legacy rows → the helper falls back to the (safe,
    // never-over-refunding) termPromoPercent formula.
    refundableTermCents: server.refundableTermCents,
    annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
  });

  // One INTERACTIVE transaction whose FIRST act is a compare-and-swap on status: flip
