  // heading naming one invoice, pre-filled with that invoice's total — but the id
  // was never sent, so the action guessed its Stripe target as "most recent top-up,
  // any amount". Refunding a $24 March invoice therefore issued $24 against the
  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
  // to refund it all over again.
  const invoiceId = String(formData.get("invoiceId") ?? "").trim();

  if (!userId) return { error: "Missing customer." };
  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };

