/** One-month credit for a flat-priced term (used by the game flow). */
export function firstMonthCreditCents(termPriceCents: number, termMonths: number): number {
  if (termMonths <= 1) return termPriceCents; // whole (single-month) term is free
  const oneMonth = Math.round(termPriceCents / termMonths);
  return Math.min(termPriceCents, oneMonth);
}

