/** The card-leg analogue of the plain wallet top-up (`app/api/stripe/checkout`'s
 *  OLD inline `ui_mode: "embedded_page"` session), for the new embedded Payment
 *  modal (components/customer/AddFundsPaymentModal.tsx). Carries no order/game/
 *  resize/expand/host/email metadata key, so `classifyCheckoutSession` falls
 *  through to its final `{ kind: "topup" }` branch exactly as the old session
 *  did — same fulfilment, only `ui_mode` (and therefore the mounted UI) differs. */
export async function createTopUpPaymentSession(
  user: CardUser,
  amountCents: number,
): Promise<CustomCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create(
    {
      mode: "payment",
      customer: customerId,
      payment_method_types: ["card"],
      payment_intent_data: { setup_future_usage: "off_session" },
      // Custom Checkout's client-side `checkout.confirm({ savePaymentMethod })`
      // (components/customer/AddFundsPaymentModal.tsx) throws `IntegrationError:
      // savePaymentMethod cannot be used unless the Checkout Session was created
      // with saved_payment_method_options[payment_method_save]=enabled` without
      // this — the same bug fixed across the four order session-builders above.
      saved_payment_method_options: { payment_method_save: "enabled" },
      expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
      line_items: [
        {
          price_data: { currency: "usd", product_data: { name: "Nxeon wallet credit" }, unit_amount: amountCents },
          quantity: 1,
        },
      ],
      // ONLY nxeonUserId — no nxeonOrder/nxeonGameOrder/etc key, so this session
      // classifies as a plain top-up (classifyCheckoutSession's final branch),
      // exactly like every other wallet top-up on the platform.
      metadata: { nxeonUserId: user.id },
      ui_mode: CUSTOM_CHECKOUT_UI_MODE,
      return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
    },
    EMBEDDED_REQUEST_OPTS,
  );
  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
}

/**
 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything
 * else is refused rather than coerced, for the same reason `parseOrderPrice`
 * refuses a half-valid price: the caller's `?? quote.prorateCents` fallback would
 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
 */
function parseChargeCents(raw: unknown): number | null {
  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
  return raw;
}

function parseId(raw: unknown): string | null {
  return typeof raw === "string" && raw.length > 0 ? raw : null;
}

/**
 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
 *
 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
 * not read this session" into "this session has no purchase metadata", and
 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
 * class of invisible failure that file was written to end, one layer up.
 *
 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
 * returning a lie) and classified by a pure function over its metadata.
 */
export type CheckoutPurpose =
=== creditCheckoutSession
 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
 * fetches it once and both the credit and the fulfilment routing read that single
 * object, so the two can never disagree about what this payment was (and a Stripe
 * read failure surfaces in one place, loudly, instead of four times as `null`).
 */
export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
  const userId = session.metadata?.nxeonUserId;
  const cents = session.amount_total ?? 0;
  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;

  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
  // session id inside the description.
  const legacy = await db.walletTransaction.findFirst({
    where: { stripeSessionId: null, description: { contains: session.id } },
  });
  if (legacy) return false;

  // Is this credit a product the customer bought, or the funding leg of something
  // else they bought? Only the first is a "Wallet top-up" and only the first gets
  // a billing document — see isPurchaseLegSession for the incident.
  const purchaseLeg = isPurchaseLegSession(session.metadata);

  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
  // read-then-write check. The confirm-redirect and the webhook can arrive
  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
  // only the database can safely decide the winner. P2002 == already credited.
  const ops: Prisma.PrismaPromise<unknown>[] = [
    db.walletTransaction.create({
      data: {
        userId,
        amountCents: cents,
        description: `Stripe payment (${session.id})`,
        stripeSessionId: session.id,
      },
    }),
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
    db.notification.create({
      data: {
        userId,
        title: `Payment of $${(cents / 100).toFixed(2)} received`,
        href: "/dashboard/billing",
      },
    }),
  ];
  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
  let invoiceOpIndex = -1;
  if (!purchaseLeg) {
    // PAID invoice for the top-up. Created in the SAME guarded transaction as
    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
    // the credit idempotent also prevents a duplicate invoice on replay.
    //
    // A purchase leg is deliberately left undocumented HERE: the order, resize or
    // disk-expansion it funds issues the one invoice for the whole purchase, and
    // that document — not this one — is what the customer's card statement shows.
    // If the fulfilment then fails the money stays in the wallet as an ordinary
    // credit (ledger row + notification), and the invoice is issued by whatever it
    // is eventually spent on; inventing a top-up document at that point would
    // double-count the same dollars all over again the moment they deploy.
    // Remember WHERE in the batch this lands, so the created row's id can be read
    // back out of the transaction result. The receipt email promises the customer
    // an attached invoice, and it can only keep that promise if it knows the id.
    invoiceOpIndex = ops.length;
    ops.push(
      db.invoice.create({
        data: invoiceCreateData({
          userId,
          description: "Wallet top-up",
          status: "PAID",
          lineItems: [
            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
          ],
        }),
      }),
    );
  }
  let invoiceId: string | undefined;
  try {
    const results = await db.$transaction(ops);
    if (invoiceOpIndex >= 0) {
      const created = results[invoiceOpIndex] as { id?: string } | undefined;
      invoiceId = created?.id;
    }
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
    throw e;
  }
  // A funded wallet is the referred user's first paid action — reward both sides.
  try {
    const { maybeRewardReferral } = await import("./actions-growth");
    await maybeRewardReferral(userId);
  } catch { /* best-effort */ }
  try {
    // On a purchase leg, skip this generic receipt entirely: the order this
    // credit is funding (VPS/hosting/email/game) issues its OWN specific,
    // itemised invoice_new email moments later (the same one fixed today to
    // correctly say "paid" rather than "due"), and it names the actual plan/
    // domain/hostname the money bought. Sending BOTH meant every purchase-
    // funding payment produced two emails: a generic, invoice-less "Payment
    // received — your Nxeon order" (real customer feedback: "this email is
    // weak") immediately followed by the real invoice — pure noise. A genuine
    // standalone top-up (not funding a specific purchase) still gets this
    // receipt, since nothing else will ever tell the customer their wallet
    // balance grew.
    if (!purchaseLeg) {
      const u = await db.user.findUnique({ where: { id: userId } });
      if (u) {
        const { sendMail, emails } = await import("./mailer");
        const tpl = emails.receipt(
          `$${(cents / 100).toFixed(2)}`,
          "wallet top-up",
          !!invoiceId,
        );
        // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
        // A receipt is ACCOUNT tier — suppressible by email if the customer
        // turned account email off.
        await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt", invoiceId });
      }
    }
  } catch { /* best-effort */ }
  return true;
}
